import { DomainError } from "./errors";
import { OrderLine } from "./order";
import { ProductRepository } from "./repositories";

/** Reserves every requested line atomically against the in-memory catalogue. */
export class StockReservationService {
  public constructor(private readonly products: ProductRepository) {}

  public reserve(lines: readonly OrderLine[]): void {
    const quantities = new Map<string, number>();
    for (const line of lines) quantities.set(line.productId, (quantities.get(line.productId) ?? 0) + line.quantity);
    const products = [...quantities].map(([productId, quantity]) => {
      const product = this.products.findById(productId);
      if (!product) throw new DomainError(`Product ${productId} does not exist`);
      if (product.availableStock < quantity) throw new DomainError(`Insufficient stock for product ${productId}`);
      return { product, quantity };
    });
    for (const { product, quantity } of products) {
      product.reserve(quantity);
      this.products.save(product);
    }
  }

  public release(lines: readonly OrderLine[]): void {
    for (const line of lines) {
      const product = this.products.findById(line.productId);
      if (!product) throw new DomainError(`Product ${line.productId} does not exist`);
      product.release(line.quantity);
      this.products.save(product);
    }
  }
}

